    pomVelX += (k * (targetX - pomAngX) - c * pomVelX) * dt;
    pomAngX += pomVelX * dt;
    pomVelZ += (k * (targetZ - pomAngZ) - c * pomVelZ) * dt;
    pomAngZ += pomVelZ * dt;
    qPom.setFromEuler(eAxis.set(THREE.MathUtils.clamp(pomAngX, -0.6, 0.6), 0, THREE.MathUtils.clamp(pomAngZ, -0.6, 0.6)));
