    blinkT -= dt;
    let blink = 1;
    if (expression !== 'dizzy') {
      if (blinkT < 0.14) blink = Math.abs(blinkT - 0.07) / 0.07;
      if (blinkT <= 0) blinkT = 2.2 + Math.random() * 2.6;
    }
